NEW_FILES = {'scripts/build-international-top-games.py': '#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""Build International Football "greatest games" data from the grand Football\nworkbook (Champions League-201516.xlsx -> Int Tournaments, column CK Game Score).\nMirrors scripts/build-{nfl,nba,mlb}-data.py top-games outputs.\n\nMen\'s tournament matches only (excludes Women\'s World Cup and 2026 World Cup).\nOutputs under public/data/international/:\n  top-games-all-time.json   (top 25 unique matches)\n  top-games-by-decade.json  (top 10 per decade)\n  top-games-by-team.json    ({slug: [top 10 this-team rows]})\n"""\nimport json, os, re, sys\nfrom pathlib import Path\nfrom collections import defaultdict\nimport openpyxl\n\nREPO_ROOT = Path(__file__).resolve().parent.parent\nALL_TIME_N, DECADE_N, TEAM_N = 50, 10, 10\n\ndef find_workbook(argv):\n    if len(argv) > 1: return Path(argv[1])\n    HOME = Path(os.path.expanduser("~"))\n    cands = [HOME/"OneDrive"/"Excel Files"/"Champions League-201516.xlsx",\n             HOME/"Library"/"CloudStorage"/"OneDrive-Personal"/"Excel Files"/"Champions League-201516.xlsx"]\n    cands += list(Path("/sessions").glob("*/mnt/Excel Files/Champions League-201516.xlsx"))\n    cands += list(Path("/sessions").glob("*/mnt/uploads/Champions League-201516.xlsx"))\n    for c in cands:\n        if c.exists(): return c\n    sys.exit("workbook not found")\n\ndef col(letter):\n    n=0\n    for ch in letter: n=n*26+(ord(ch)-64)\n    return n-1\nCOLS={k:col(k) for k in [\'J\',\'K\',\'M\',\'N\',\'O\',\'L\',\'T\',\'U\',\'S\',\'BI\',\'BJ\',\'F\',\'H\',\'P\',\'Q\',\'R\',\'CK\',\'C\',\'CB\',\'AD\']}\ndef mn(s): return re.sub(r\'[^a-z0-9]\',\'\',str(s or \'\').lower())\n\ndef main():\n    REPO = Path(os.environ.get("COW_REPO", str(REPO_ROOT)))\n    OUT = Path(os.environ.get("COW_OUT", str(REPO/"public"/"data"/"international")))\n    OUT.mkdir(parents=True, exist_ok=True)\n    wb_path = find_workbook(sys.argv)\n    # resolver: name -> slug from slug-lookup.json (+ index.json fallback)\n    idir = REPO/"public"/"data"/"international"\n    resolver={}\n    try:\n        sl=json.load(open(idir/"slug-lookup.json", encoding="utf-8"))\n        for k,v in sl.items(): resolver[mn(k)]=v\n    except Exception: pass\n    try:\n        idx=json.load(open(idir/"index.json", encoding="utf-8"))\n        for t in (idx if isinstance(idx,list) else idx.get("teams",[])):\n            for k in (t.get("cur_name"),t.get("name"),t.get("slug")):\n                if k and mn(k) not in resolver: resolver[mn(k)]=t["slug"]\n    except Exception: pass\n    def slug(name): return resolver.get(mn(name))\n\n    wb=openpyxl.load_workbook(wb_path, read_only=True, data_only=True)\n    ws=wb["Int Tournaments"]\n    g=lambda r,k: r[COLS[k]].value\n    rows=[]\n    for r in ws.iter_rows(min_row=2):\n        if g(r,\'K\') is None or g(r,\'CK\') is None: continue\n        if g(r,\'F\')=="Women\'s World Cup": continue\n        if g(r,\'C\')==2026: continue\n        rows.append({\n            \'date\':(str(g(r,\'J\'))[:10] if g(r,\'J\') else None),\'year\':g(r,\'C\'),\n            \'team\':g(r,\'K\'),\'opp\':g(r,\'M\'),\'for\':g(r,\'N\'),\'ag\':g(r,\'O\'),\'res\':g(r,\'L\'),\n            \'pkself\':g(r,\'T\'),\'pkopp\':g(r,\'U\'),\'tiebrk\':g(r,\'S\'),\n            \'comp\':g(r,\'F\'),\'round\':g(r,\'H\'),\'stadium\':g(r,\'P\'),\'metro\':g(r,\'Q\'),\'country\':g(r,\'R\'),\n            \'team_slug\':slug(g(r,\'BI\')),\'opp_slug\':slug(g(r,\'BJ\')),\'elo\':g(r,\'CB\'),\n            \'home\':(g(r,\'AD\')==\'Home\'),\'gs\':round(float(g(r,\'CK\')),4)})\n    wb.close()\n\n    # ---- unique matches (winner/loser/draw) ----\n    groups=defaultdict(list)\n    for x in rows: groups[(x[\'date\'],frozenset((mn(x[\'team\']),mn(x[\'opp\']))))].append(x)\n    matches=[]\n    for k,pair in groups.items():\n        w=next((p for p in pair if p[\'res\']==\'W\'), None)\n        if w:\n            l=next((p for p in pair if p is not w), w)\n            is_draw=False; win,lose=w,l\n        else:\n            ranked=sorted(pair, key=lambda p:-(p[\'elo\'] or 0))\n            win,lose=ranked[0],(ranked[1] if len(ranked)>1 else ranked[0]); is_draw=True\n        pens=None\n        if win[\'pkself\'] is not None and win[\'pkopp\'] is not None:\n            pens=f"{win[\'pkself\']}-{win[\'pkopp\']}"\n        matches.append({\n            \'year\':win[\'year\'],\'date\':win[\'date\'],\'competition\':win[\'comp\'],\'round\':win[\'round\'],\n            \'winner_name\':win[\'team\'],\'winner_slug\':win[\'team_slug\'],\n            \'loser_name\':lose[\'team\'],\'loser_slug\':lose[\'team_slug\'],\n            \'winner_score\':win[\'for\'],\'loser_score\':win[\'ag\'],\'is_draw\':is_draw,\'pens\':pens,\n            \'stadium\':win[\'stadium\'],\'stadium_metro\':win[\'metro\'],\'stadium_country\':win[\'country\'],\n            \'game_score\':win[\'gs\']})\n    matches.sort(key=lambda m:-m[\'game_score\'])\n\n    all_time=matches[:ALL_TIME_N]\n    by_decade=defaultdict(list)\n    for m in matches:\n        if m[\'year\']: by_decade[str((int(m[\'year\'])//10)*10)].append(m)\n    by_decade={k:v[:DECADE_N] for k,v in sorted(by_decade.items())}\n\n    # ---- per-team (this-team perspective) ----\n    team_rows=defaultdict(list)\n    for x in rows:\n        s=x[\'team_slug\']\n        if not s: continue\n        pens=None\n        if x[\'pkself\'] is not None and x[\'pkopp\'] is not None: pens=f"{x[\'pkself\']}-{x[\'pkopp\']}"\n        team_rows[s].append({\n            \'year\':x[\'year\'],\'date\':x[\'date\'],\'competition\':x[\'comp\'],\'round\':x[\'round\'],\n            \'team_name\':x[\'team\'],\'team_slug\':s,\'opp_name\':x[\'opp\'],\'opp_slug\':x[\'opp_slug\'],\n            \'for_score\':x[\'for\'],\'against_score\':x[\'ag\'],\'result\':x[\'res\'],\'pens\':pens,\'is_home\':x[\'home\'],\n            \'stadium\':x[\'stadium\'],\'stadium_metro\':x[\'metro\'],\'stadium_country\':x[\'country\'],\n            \'game_score\':x[\'gs\']})\n    by_team={s:sorted(v,key=lambda r:-r[\'game_score\'])[:TEAM_N] for s,v in team_rows.items()}\n\n    json.dump(all_time, open(OUT/"top-games-all-time.json","w",encoding="utf-8"), ensure_ascii=False, separators=(",",":"))\n    json.dump(by_decade, open(OUT/"top-games-by-decade.json","w",encoding="utf-8"), ensure_ascii=False, separators=(",",":"))\n    json.dump(by_team, open(OUT/"top-games-by-team.json","w",encoding="utf-8"), ensure_ascii=False, separators=(",",":"))\n    print(f"unique matches: {len(matches)} | all-time: {len(all_time)} | decades: {len(by_decade)} | teams: {len(by_team)}")\n    print("decade keys:", list(by_decade))\n    print("\\nTOP 8 all-time:")\n    for m in all_time[:8]:\n        d="(draw)" if m[\'is_draw\'] else ""; p=f" pens {m[\'pens\']}" if m[\'pens\'] else ""\n        print(f"  {m[\'game_score\']:.3f} {m[\'date\']} {m[\'winner_name\']} {m[\'winner_score\']}-{m[\'loser_score\']} {m[\'loser_name\']} {d}{p} | {m[\'competition\']}/{m[\'round\']} | {m[\'stadium_metro\']} | slugs {m[\'winner_slug\']}/{m[\'loser_slug\']}")\n    print("\\nGermany top 3:")\n    for r in by_team.get(\'germany\',[])[:3]:\n        print(f"  {r[\'game_score\']:.3f} {r[\'date\']} {r[\'result\']} {r[\'team_name\']} {r[\'for_score\']}-{r[\'against_score\']} {r[\'opp_name\']} | {r[\'competition\']}/{r[\'round\']}")\n    miss_w=sum(1 for m in matches if not m[\'winner_slug\']); miss_t=sum(1 for s,v in by_team.items() for r in v if not r[\'opp_slug\'])\n    print(f"\\nunmapped winner slugs: {miss_w} | by-team rows with unmapped opp: {miss_t}")\n\nif __name__=="__main__": main()\n', 'app/teams/national/TopGamesTable.tsx': '"use client";\n\nimport Link from "next/link";\nimport { useState } from "react";\nimport type { TopGameNationalRow } from "@/lib/international";\nimport { WatchButton, type GameVideo } from "@/app/teams/_shared/GameVideo";\n\n// International Football "greatest games" table, mirroring the NFL/NBA/MLB\n// TopGamesTable: an all-time list plus a per-decade filter, ranked by the\n// workbook Game Score. Football-specific: shows competition + stage, marks\n// draws (decided on penalties) and links both nations to their team pages.\ntype Row = TopGameNationalRow & { video?: GameVideo };\ntype Props = { allTime: Row[]; byDecade: Record<string, Row[]>; allTimeLabel?: string };\n\nfunction decadeKeys(b: Record<string, Row[]>): string[] {\n  return Object.keys(b).filter((k) => /^\\d{4}$/.test(k)).sort((a, c) => Number(c) - Number(a));\n}\n\nexport default function TopGamesTable({ allTime, byDecade, allTimeLabel = "All-time top 50" }: Props) {\n  const [bucket, setBucket] = useState<string>("all");\n  const rows = bucket === "all" ? allTime : (byDecade[bucket] ?? []);\n  const decades = decadeKeys(byDecade);\n  const pill = (active: boolean) =>\n    active\n      ? { background: "var(--accent-dim)", color: "var(--text)", borderColor: "var(--accent-dim)" }\n      : { background: "var(--bg-card)", color: "var(--text-muted)", borderColor: "var(--border)" };\n\n  return (\n    <section className="rounded-xl border p-5 mt-4" style={{ background: "var(--bg-card)", borderColor: "var(--border)" }}>\n      <h2 className="text-base font-semibold">Top games of all-time</h2>\n      <p className="text-xs text-[var(--text-muted)] mt-1 mb-3">\n        Ranked by the site&apos;s Game Score (ELO) metric, which combines hype, quality, stakes, and matchup rank.\n        Switch the filter for the top 10 of any decade.\n        <a href="/methodology#game-score" className="hover:text-[var(--text)] ml-1 underline decoration-dotted">Methodology</a>.\n      </p>\n\n      <div className="flex flex-wrap gap-1.5 mb-4">\n        <button type="button" onClick={() => setBucket("all")} className="text-xs px-3 py-1 rounded-full border transition-colors" style={pill(bucket === "all")}>\n          {allTimeLabel}\n        </button>\n        {decades.map((d) => (\n          <button key={d} type="button" onClick={() => setBucket(d)} className="text-xs px-3 py-1 rounded-full border transition-colors" style={pill(bucket === d)}>\n            {d}s\n          </button>\n        ))}\n      </div>\n\n      <div className="max-h-[70vh] overflow-auto">\n        <table className="w-full text-xs tabular-nums [&_thead_th]:sticky [&_thead_th]:top-0 [&_thead_th]:z-10 [&_thead_th]:bg-[var(--bg)]">\n          <thead>\n            <tr className="text-[var(--text-muted)]">\n              <th className="text-left font-medium py-2 uppercase tracking-wider text-[10px] pr-3">#</th>\n              <th className="text-left font-medium py-2 uppercase tracking-wider text-[10px] pr-3">Date</th>\n              <th className="text-left font-medium py-2 uppercase tracking-wider text-[10px] pr-3">Stage</th>\n              <th className="text-left font-medium py-2 uppercase tracking-wider text-[10px] pr-3">Match</th>\n              <th className="text-right font-medium py-2 uppercase tracking-wider text-[10px]">Game Score</th>\n            </tr>\n          </thead>\n          <tbody>\n            {rows.map((g, i) => (\n              <tr key={`${g.year}-${g.winner_name}-${g.loser_name}-${i}`} className="border-t" style={{ borderColor: "var(--border)" }}>\n                <td className="py-2 pr-3 text-[var(--text-muted)]">{i + 1}</td>\n                <td className="py-2 pr-3 whitespace-nowrap">{g.date ?? g.year}</td>\n                <td className="py-2 pr-3 text-[var(--text-muted)] whitespace-nowrap">\n                  {g.competition}{g.round ? ` · ${g.round}` : ""}\n                </td>\n                <td className="py-2 pr-3">\n                  <div className="leading-tight">\n                    {g.winner_slug ? (\n                      <Link href={`/teams/national/${g.winner_slug}`} className="font-semibold hover:text-[var(--accent)] hover:underline decoration-dotted underline-offset-2">{g.winner_name}</Link>\n                    ) : (\n                      <span className="font-semibold">{g.winner_name}</span>\n                    )}{" "}\n                    <span className="tabular-nums font-semibold" style={{ color: "var(--accent)" }}>{g.winner_score}</span>\n                    <span className="mx-1 text-[var(--text-dim)]">{g.is_draw ? "=" : "-"}</span>\n                    <span className="tabular-nums text-[var(--text-muted)]">{g.loser_score}</span>{" "}\n                    {g.loser_slug ? (\n                      <Link href={`/teams/national/${g.loser_slug}`} className="text-[var(--text-muted)] hover:text-[var(--accent)] hover:underline decoration-dotted underline-offset-2">{g.loser_name}</Link>\n                    ) : (\n                      <span className="text-[var(--text-muted)]">{g.loser_name}</span>\n                    )}\n                    {g.pens ? <span className="ml-1 text-[10px] text-[var(--text-dim)]">(pens {g.pens})</span> : null}\n                  </div>\n                  {g.stadium ? (\n                    <div className="text-[10px] mt-0.5 truncate font-medium tracking-wide" style={{ color: "var(--text-dim)", fontFamily: "\'JetBrains Mono\', monospace" }} title={[g.stadium, g.stadium_metro, g.stadium_country].filter(Boolean).join(" — ")}>\n                      {g.stadium}{g.stadium_metro ? <span className="ml-1 opacity-80">· {g.stadium_metro}{g.stadium_country ? `, ${g.stadium_country}` : ""}</span> : null}\n                    </div>\n                  ) : null}\n                  {g.video ? <WatchButton video={g.video} /> : null}\n                </td>\n                <td className="py-2 text-right font-semibold">{g.game_score.toFixed(3)}</td>\n              </tr>\n            ))}\n            {rows.length === 0 && (\n              <tr><td colSpan={5} className="py-6 text-center text-[var(--text-dim)] italic">No games in this bucket.</td></tr>\n            )}\n          </tbody>\n        </table>\n      </div>\n    </section>\n  );\n}\n', 'app/teams/national/TeamTopGames.tsx': '"use client";\n\nimport Link from "next/link";\nimport type { TopGameNationalTeamRow } from "@/lib/international";\n\n// Per-team "greatest games" on a national-team page: this team\'s top tournament\n// matches by Game Score, this-team perspective (result W/D/L, score, opponent).\nconst RES: Record<string, { label: string; color: string }> = {\n  W: { label: "W", color: "var(--accent)" },\n  D: { label: "D", color: "var(--text-muted)" },\n  L: { label: "L", color: "var(--text-dim)" },\n};\n\nexport default function TeamTopGames({ rows, teamName }: { rows: TopGameNationalTeamRow[]; teamName: string }) {\n  if (!rows || rows.length === 0) return null;\n  return (\n    <section className="rounded-xl border p-5 mb-6" style={{ background: "var(--bg-card)", borderColor: "var(--border)" }}>\n      <h2 className="text-base font-semibold">Greatest games</h2>\n      <p className="text-xs text-[var(--text-muted)] mt-1 mb-3">\n        {teamName}&apos;s top tournament matches by the site&apos;s Game Score (ELO).\n        <a href="/methodology#game-score" className="ml-1 underline decoration-dotted hover:text-[var(--text)]">Methodology</a>.\n      </p>\n      <div className="overflow-x-auto">\n        <table className="w-full text-xs tabular-nums">\n          <thead>\n            <tr className="text-[var(--text-muted)]">\n              <th className="text-left font-medium py-2 uppercase tracking-wider text-[10px] pr-3">#</th>\n              <th className="text-left font-medium py-2 uppercase tracking-wider text-[10px] pr-3">Date</th>\n              <th className="text-left font-medium py-2 uppercase tracking-wider text-[10px] pr-3">Stage</th>\n              <th className="text-left font-medium py-2 uppercase tracking-wider text-[10px] pr-3">Result</th>\n              <th className="text-right font-medium py-2 uppercase tracking-wider text-[10px]">Game Score</th>\n            </tr>\n          </thead>\n          <tbody>\n            {rows.map((g, i) => {\n              const r = RES[g.result] ?? RES.D;\n              return (\n                <tr key={`${g.year}-${g.opp_name}-${i}`} className="border-t" style={{ borderColor: "var(--border)" }}>\n                  <td className="py-2 pr-3 text-[var(--text-muted)]">{i + 1}</td>\n                  <td className="py-2 pr-3 whitespace-nowrap">{g.date ?? g.year}</td>\n                  <td className="py-2 pr-3 text-[var(--text-muted)] whitespace-nowrap">{g.competition}{g.round ? ` · ${g.round}` : ""}</td>\n                  <td className="py-2 pr-3">\n                    <span className="font-semibold" style={{ color: r.color }}>{r.label}</span>{" "}\n                    <span className="tabular-nums">{g.for_score}-{g.against_score}</span>{" "}\n                    <span className="text-[var(--text-muted)]">v</span>{" "}\n                    {g.opp_slug ? (\n                      <Link href={`/teams/national/${g.opp_slug}`} className="hover:text-[var(--accent)] hover:underline decoration-dotted underline-offset-2">{g.opp_name}</Link>\n                    ) : (\n                      <span>{g.opp_name}</span>\n                    )}\n                    {g.pens ? <span className="ml-1 text-[10px] text-[var(--text-dim)]">(pens {g.pens})</span> : null}\n                  </td>\n                  <td className="py-2 text-right font-semibold">{g.game_score.toFixed(3)}</td>\n                </tr>\n              );\n            })}\n          </tbody>\n        </table>\n      </div>\n    </section>\n  );\n}\n'}

