REL_BULLET = 'New International Football greatest games: a top-25 board with decade filter on the international hub, a top-10 list on every national team page, and the section leading the cross-sport Greatest Games page.'
REL_NEWBLOCK = 'export const RELEASES: Release[] = [\n  {\n    date: "2026-06-23",\n    headline: "International Football joins the Greatest Games",\n    items: [\n      "New International Football greatest games: a top-25 board with decade filter on the international hub, a top-10 list on every national team page, and the section leading the cross-sport Greatest Games page.",\n    ],\n  },\n  {\n    date: "2026-06-22",'

def write_new(rel, content):
    p = os.path.join(REPO, *rel.split("/"))
    os.makedirs(os.path.dirname(p), exist_ok=True)
    if os.path.exists(p):
        print("[skip] exists:", rel); return
    with open(p, "w", encoding="utf-8", newline="\n") as f:
        f.write(content)
    print("[ok]   wrote", rel)

def edit(rel, anchor, repl):
    p = os.path.join(REPO, *rel.split("/"))
    raw = open(p, "rb").read()
    bom = raw.startswith(b"\xef\xbb\xbf")
    text = raw.decode("utf-8-sig"); crlf = "\r\n" in text
    norm = text.replace("\r\n", "\n")
    if repl in norm:
        print("[skip] already applied in", rel); return
    n = norm.count(anchor)
    if n != 1:
        sys.exit("[ABORT] %s anchor x%d:\n  %r" % (rel, n, anchor[:80]))
    norm = norm.replace(anchor, repl, 1)
    out = norm.replace("\n", "\r\n") if crlf else norm
    data = (b"\xef\xbb\xbf" if bom else b"") + out.encode("utf-8")
    open(p, "wb").write(data)
    print("[ok]   edited", rel)

def release_note():
    p = os.path.join(REPO, "lib", "releases.ts")
    raw = open(p, "rb").read(); bom = raw.startswith(b"\xef\xbb\xbf")
    text = raw.decode("utf-8-sig"); crlf = "\r\n" in text
    norm = text.replace("\r\n", "\n")
    if REL_BULLET in norm:
        print("[skip] release note present"); return
    if 'date: "2026-06-23"' in norm:
        i = norm.index('date: "2026-06-23"')
        j = norm.index("items: [", i)
        ins = norm.index("\n", j) + 1
        norm = norm[:ins] + '      "%s",\n' % REL_BULLET + norm[ins:]
        print("[ok]   merged bullet into existing 2026-06-23 block")
    else:
        a = 'export const RELEASES: Release[] = [\n  {\n    date: "2026-06-22",'
        if norm.count(a) != 1: sys.exit("[ABORT] releases anchor")
        norm = norm.replace(a, REL_NEWBLOCK, 1)
        print("[ok]   added 2026-06-23 release block")
    out = norm.replace("\n", "\r\n") if crlf else norm
    open(p, "wb").write((b"\xef\xbb\xbf" if bom else b"") + out.encode("utf-8"))

def main():
    for rel, c in NEW_FILES.items(): write_new(rel, c)
    for rel, a, r in EDITS: edit(rel, a, r)
    release_note()
    if SKIP_BUILD:
        print("[dry] skipping build"); return
    print("[run] python scripts/build-international-top-games.py")
    subprocess.check_call([sys.executable, os.path.join("scripts","build-international-top-games.py")], cwd=REPO)
    print("\nDone. Next: npx tsc --noEmit  &&  node scripts/check-client-imports.mjs")

if __name__ == "__main__": main()
